function format(value, replacements = {}) {
  return String(value || '').replace(/\{([a-zA-Z]+)\}/g, (_, key) => String(replacements[key] ?? ''));
}

function normalizeProduct(value) {
  const key = String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  if (['cv','cv_analysis','talent_scan'].includes(key)) return 'cv_analysis';
  if (['video_presentation','presentation','vp'].includes(key)) return 'video_presentation';
  if (['ai_literacy','ai_literacy_qualification','ail'].includes(key)) return 'ai_literacy';
  return ['interview','assessment','snapshot'].includes(key) ? key : 'assessment';
}

function normalizeMode(value) {
  const mode = String(value || 'standard').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  return ['chat','audio','video','mix','audio_chat','video_chat','upload','standard'].includes(mode) ? mode : 'standard';
}

export function normalizeCandidateExperienceLocale(value = 'en') {
  const code = String(value || 'en').trim().toLowerCase().split(/[-_]/)[0];
  return CANDIDATE_EXPERIENCE_LANGUAGES.includes(code) ? code : 'en';
}

function stepsFor(copy, productKey) {
  if (productKey === 'cv_analysis') return copy.stepsCv;
  if (productKey === 'video_presentation') return copy.stepsVp;
  if (productKey === 'ai_literacy') return copy.stepsAi;
  return copy.stepsDefault;
}

function tipsFor(copy, productKey, mode) {
  const tips = [...copy.tips];
  if (productKey === 'cv_analysis') tips.push(copy.tipUpload);
  else if (productKey === 'video_presentation' || mode === 'video' || mode === 'video_chat') tips.push(copy.tipVideo);
  else if (mode === 'audio' || mode === 'audio_chat' || mode === 'mix') tips.push(copy.tipAudio);
  else tips.push(copy.tipChat);
  return tips.filter(Boolean);
}

function brandNames(copy, branding, brandingMode) {
  const company = String(branding?.reportBrandName || branding?.brandName || branding?.companyName || 'Company').trim() || 'Company';
  const mode = brandingMode === 'whitelabel' ? 'whitelabel' : brandingMode === 'cobranded' ? 'cobranded' : 'clarity';
  if (mode === 'whitelabel') return { company, welcome:format(copy.welcomeWhite,{company}), publicBrand:company };
  if (mode === 'cobranded') return { company, welcome:format(copy.welcomeCo,{company}), publicBrand:format(copy.jointBrand,{company}) };
  return { company, welcome:copy.welcomeStandard, publicBrand:'CLARITY' };
}

export function buildCandidateExperience(input = {}, locale = 'en') {
  const language = normalizeCandidateExperienceLocale(locale);
  const copy = COPY[language] || COPY.en;
  const runtime = input.runtime || {};
  const branding = input.branding || {};
  const productKey = normalizeProduct(runtime.productKey);
  const mode = normalizeMode(runtime.mode || runtime.workflowSnapshot?.mode);
  const countValue = Number(runtime.questionCount || runtime.workflowSnapshot?.questionCount || 0);
  const count = Number.isFinite(countValue) && countValue > 0 ? Math.round(countValue) : 0;
  const scope = count ? format(copy.questions,{count}) : copy.modes[mode];
  let modeSentence = copy.written;
  if (['mix','audio_chat','video_chat'].includes(mode) && count) {
    const spoken = count === 10 ? 7 : Math.ceil(count * 0.7);
    modeSentence = format(copy.hybrid,{spoken,written:Math.max(0,count-spoken)});
  } else if (mode === 'audio') modeSentence = copy.oral;
  else if (mode === 'video') modeSentence = copy.video;
  else if (mode === 'chat') modeSentence = copy.written;
  else if (productKey === 'cv_analysis' || productKey === 'video_presentation' || productKey === 'ai_literacy') modeSentence = '';
  const brand = brandNames(copy, branding, input.brandingMode);
  const product = copy.products[productKey] || copy.products.assessment;
  const summary = format(copy.summaries[productKey] || copy.summaries.assessment,{scope,mode:modeSentence}).replace(/\s+/g,' ').trim();
  const position = String(runtime.position || runtime.purpose || runtime.configurationSnapshot?.position || '').trim();
  const context = position ? format(copy.position,{position}) : '';
  const feedback = {};
  Object.keys(copy.feedback).forEach((key) => {
    feedback[key] = format(copy.feedback[key],{product,brand:brand.publicBrand});
  });
  return {
    version:CANDIDATE_EXPERIENCE_VERSION,
    locale:language,
    direction:language === 'ar' ? 'rtl' : 'ltr',
    productKey,
    product,
    mode,
    modeLabel:copy.modes[mode] || copy.modes.standard,
    questionLabel:count ? format(copy.questions,{count}) : '',
    eyebrow:copy.secure,
    welcomeTitle:brand.welcome,
    summary,
    context,
    whatTitle:copy.whatTitle,
    howTitle:copy.howTitle,
    tipsSummary:copy.tipsSummary,
    steps:stepsFor(copy,productKey),
    tips:tipsFor(copy,productKey,mode),
    readyTitle:copy.readyTitle,
    readyText:copy.readyText,
    startLabel:copy.start[productKey] || copy.start.assessment,
    feedback
  };
}
